import{_ as s,o as t,c as a,a0 as o}from"./chunks/framework.tsJrOMu2.js";const u=JSON.parse('{"title":"Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/sessions.md","filePath":"concepts/sessions.md"}'),n={name:"concepts/sessions.md"};function i(r,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h1><p>A session is the unit of conversation persistence in Agentrail. It holds the message history for a single user&#39;s ongoing conversation with an agent.</p><h2 id="what-a-session-is" tabindex="-1">What a Session Is <a class="header-anchor" href="#what-a-session-is" aria-label="Permalink to &quot;What a Session Is&quot;">​</a></h2><p>Each session has:</p><ul><li>a unique <code>sessionId</code> (UUID)</li><li>an owner identity: <code>tenantId</code> + <code>userId</code> + <code>agentId</code></li><li>an ordered list of messages (the conversation history)</li><li>a cumulative token usage record</li></ul><p>Sessions are created on the first request and resumed on subsequent requests by passing the <code>sessionId</code> in the request body. If no <code>sessionId</code> is provided, a new session is created automatically.</p><h2 id="session-lifecycle" tabindex="-1">Session Lifecycle <a class="header-anchor" href="#session-lifecycle" aria-label="Permalink to &quot;Session Lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>First request (no sessionId)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>getOrCreate → new session created → sessionId returned in response</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>Client stores sessionId and sends it on subsequent requests</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>getOrCreate → existing session resumed</span></span></code></pre></div><h2 id="session-store-contract" tabindex="-1">Session Store Contract <a class="header-anchor" href="#session-store-contract" aria-label="Permalink to &quot;Session Store Contract&quot;">​</a></h2><p>The host layer depends on the <code>AgentrailSessionStore</code> contract rather than any concrete storage implementation. This means you can swap out the storage backend without changing your host code.</p><p>The required contract includes:</p><table tabindex="0"><thead><tr><th>Method</th><th>Called when</th></tr></thead><tbody><tr><td><code>getOrCreate</code></td><td>Every request — creates or resumes the session</td></tr><tr><td><code>loadMessagesWithBudget</code></td><td>Every request — loads history trimmed to the token budget</td></tr><tr><td><code>loadAllMessages</code></td><td>During compaction — loads full history to assess whether to compact</td></tr><tr><td><code>appendMessages</code></td><td>After agent completes — persists the new turn&#39;s messages</td></tr><tr><td><code>recordTurn</code></td><td>After agent completes — persists token usage</td></tr><tr><td><code>compactIfNeeded</code></td><td>During each request — summarizes old history if token threshold is exceeded</td></tr></tbody></table><p>Additional optional methods (<code>readMemoryDocument</code>, <code>writeMemoryDocument</code>, <code>readToolResultArtifact</code>, <code>writeToolResultArtifact</code>) unlock memo tools and tool-result compaction. When also passing your store as <code>memoProvider</code> to <code>SandboxManager</code>, implement <code>listToolResultArtifactIds</code> as part of the <code>SandboxMemoProvider</code> contract to enable full <code>/workspace/memo/**</code> sandbox access. See <a href="./../reference/session-store">Session Store Reference</a> for the complete interface.</p><h2 id="default-implementation-sessionmanager" tabindex="-1">Default Implementation: <code>SessionManager</code> <a class="header-anchor" href="#default-implementation-sessionmanager" aria-label="Permalink to &quot;Default Implementation: \`SessionManager\`&quot;">​</a></h2><p>The default session store is <code>SessionManager</code> from <code>@agentrail/app</code>. It uses the local filesystem to persist sessions, with one directory per session:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { SessionManager } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@agentrail/app&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sessionManager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tmp/agentrail-sessions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>The path is the root directory under which all tenant/session data is stored. In production, point <code>dataDir</code> at a persistent volume so sessions survive container restarts. For multi-instance deployments, mount a shared filesystem (NFS, EFS, etc.) at the same path on all instances.</p><h2 id="turn-persistence" tabindex="-1">Turn Persistence <a class="header-anchor" href="#turn-persistence" aria-label="Permalink to &quot;Turn Persistence&quot;">​</a></h2><p>A <strong>turn</strong> is one complete interaction: a user message followed by the agent&#39;s full response (which may involve multiple LLM calls and tool executions).</p><p>After each turn, the host:</p><ol><li>Calls <code>appendMessages</code> to write the new user and assistant messages</li><li>Calls <code>recordTurn</code> to record token usage for billing or observability</li></ol><p>During streaming, <code>appendMessages</code> is called incrementally after each internal reasoning turn (one LLM call plus any tool executions it triggers), rather than once at the end of the full interaction. This means messages are durable on disk as soon as each reasoning step completes, not only after the SSE stream closes. <code>recordTurn</code> is still called once when the entire interaction finishes. Plugins can react to this via the <code>onTurnPersisted</code> hook.</p><blockquote><p><strong>Note:</strong> &quot;internal reasoning turn&quot; here refers to the runtime&#39;s <code>turn.complete</code> event, which is distinct from the public session concept of a &quot;turn&quot; (one full user interaction).</p></blockquote><h2 id="history-loading-with-token-budget" tabindex="-1">History Loading with Token Budget <a class="header-anchor" href="#history-loading-with-token-budget" aria-label="Permalink to &quot;History Loading with Token Budget&quot;">​</a></h2><p>The host does not load unlimited history. On each request, it calls <code>loadMessagesWithBudget</code> to retrieve as many recent messages as fit within the model&#39;s context window (minus room for the current turn and context providers).</p><p>This ensures the context window is never overflowed by long sessions. The <code>contextWindow</code> field on the profile controls the token limit used for this calculation.</p><p>For long-running single requests, Agentrail can also apply in-loop reactive compaction before the next model call. That path rewrites only the in-memory request history; persisted session files are still managed by request-boundary compaction.</p><h2 id="implementing-a-custom-store" tabindex="-1">Implementing a Custom Store <a class="header-anchor" href="#implementing-a-custom-store" aria-label="Permalink to &quot;Implementing a Custom Store&quot;">​</a></h2><p>For most deployments, <code>SessionManager</code> with a persistent or shared volume is the recommended approach. For advanced use cases where the <code>AgentrailSessionStore</code> interface needs to be implemented from scratch (for example, integrating with an existing message persistence layer or adding custom access controls), any object satisfying the interface can be passed via <code>sessionStore</code>.</p><p>See the <a href="./../reference/session-store">Session Store Reference</a> for the full interface and <a href="./../guides/build-a-storage-backend">Build a Storage Backend</a> for a complete implementation guide.</p><h2 id="related-concepts" tabindex="-1">Related Concepts <a class="header-anchor" href="#related-concepts" aria-label="Permalink to &quot;Related Concepts&quot;">​</a></h2><ul><li><a href="./host">Host</a></li><li><a href="./context-and-compaction">Context &amp; Compaction</a></li><li><a href="./profiles">Profiles</a></li></ul><h2 id="related-reference" tabindex="-1">Related Reference <a class="header-anchor" href="#related-reference" aria-label="Permalink to &quot;Related Reference&quot;">​</a></h2><ul><li><a href="./../reference/session-store">Session Store Reference</a></li></ul>`,34)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
